/* Quiet initial view; selected tools stay spatially attached to the miniature. */
let activeWorkspace='home';
const workspaceRoots={explore:'regions',words:'vocabulary',guide:'guideControls',music:'musicControls',lens:'toolControls'};
function renderToolControls(){const root=$('toolControls');if(window.globiquest.renderMagicLensControls){window.globiquest.renderMagicLensControls(root);return}dispose(root);panel(root,{kicker:'INSPECT',title:'Magnifying glass',width:2.35,height:.5,y:.8,font:53});panel(root,{title:'Zoom '+state.zoom+'×',width:2.25,height:.35,y:.23,font:55,align:'center',accent:true,action:()=>{cycleZoom();renderToolControls();applyWorkspace()}});panel(root,{title:'Move to other side',width:2.25,height:.35,y:-.23,font:50,align:'center',action:moveLens});panel(root,{title:'Pinch or drag the lens to place it. Quest: hold grip to inspect the globe.',width:2.35,height:.62,y:-.84,font:39})}
function setWorkspace(mode='home',force=false){window.globiquest.closeWaterView?.();window.globiquest.globePatch?.disarm?.();window.globiquest.closeKaleidoscope?.();window.globiquest.closeTravel?.();window.globiquest.closeScope?.();if(!['home',...Object.keys(workspaceRoots)].includes(mode))return;if(featureOpen)closeAdventure();activeWorkspace=!force&&mode===activeWorkspace?'home':mode;releaseLens();document.getElementById('earthRoot')?.components?.['globe-rotation']?.release();renderNav();if(activeWorkspace==='lens')renderToolControls();else if(activeWorkspace==='words')renderVocabulary();else if(activeWorkspace==='explore'){window.globiquest.ensurePlacePins?.();renderRegions()}else if(activeWorkspace==='guide')renderNova();applyWorkspace();if(activeWorkspace==='music')window.globiquest.restoreTinyWorld?.();if(workspaceRoots[activeWorkspace])window.globiquest.presentTaskPanel?.(workspaceRoots[activeWorkspace])}
function buildFeatureIsland(){if($('featureIsland'))return;const root=entity('a-entity',{id:'featureIsland',visible:false},scene);entity('a-cylinder',{radius:1.35,height:.12,color:'#b1c7a6',position:'0 -.05 0'},root);entity('a-cone',{'radius-top':1.35,'radius-bottom':.3,height:.7,color:'#788f89',position:'0 -.46 0','segments-radial':9},root);entity('a-torus',{radius:1.29,'radius-tubular':.018,rotation:'90 0 0',color:'#e8d8ac',position:'0 .02 0'},root);for(let i=0;i<8;i++)entity('a-box',{width:.17,height:.035,depth:.42,position:`${-1.15-i*.13} ${-.01+Math.sin(i/7*Math.PI)*.06} 0`,color:'#dfceb0'},root)}
function applyWorkspace(){const vr=scene.is('vr-mode'),compact=!vr&&(window.innerWidth||1440)/(window.innerHeight||900)<1.1;const open=activeWorkspace!=='home'||featureOpen;$('spatialDock').hidden=vr;document.querySelectorAll('[data-workspace]').forEach(button=>button.setAttribute('aria-pressed',!featureOpen&&button.dataset.workspace===activeWorkspace?'true':'false'));Object.entries(workspaceRoots).forEach(([mode,id])=>{showEntity(id,!featureOpen&&mode===activeWorkspace);$(id).setAttribute('position',compact?'0 1.3 .7':'2.85 1.85 -.45');$(id).setAttribute('rotation',compact?'0 0 0':'0 -25 0')});const heroX=open&&!compact?-.8:0;showEntity('mapRoot',true);showEntity('environment',true);showEntity('destination',!featureOpen&&activeWorkspace==='explore'&&!window.globiquest.destinationDetailsOpen);if(!$('mapRoot').components?.['bimanual-globe']?.placed){$('mapRoot').setAttribute('position',`${heroX} ${compact?2.35:2.65} -1.8`);$('mapRoot').setAttribute('scale',compact?'.88 .88 .88':'1 1 1');}$('environment').setAttribute('position',`${heroX} ${compact?.65:.7} ${compact?-.63:-.25}`);$('environment').setAttribute('scale',compact?'.65 .65 .65':'.86 .86 .86');$('questReward').setAttribute('position',`${heroX} ${compact?.65:.7} ${compact?-.63:-.25}`);$('questReward').setAttribute('scale',compact?'.65 .65 .65':'.86 .86 .86');$('destination').setAttribute('position',`${heroX} ${compact?3.5:3.95} -1.8`);showEntity('nav',vr);showEntity('nova',!featureOpen&&activeWorkspace==='guide');showEntity('novaCaption',false);showEntity('lens',!featureOpen&&activeWorkspace==='lens');window.globiquest.showGuitarCorner?.(!featureOpen&&activeWorkspace==='music');$('nova').setAttribute('animation',compact?'property:position; from:0 3.1 .9; to:0 3.15 .9; dir:alternate; loop:true; dur:2800':'property:position; from:2.85 3.65 -.35; to:2.85 3.7 -.35; dir:alternate; loop:true; dur:2800');if(!state.lensHeld&&!$('lens').dataset?.userPlaced){$('lens').setAttribute('position',compact?'-.75 2.4 -.8':'-2.7 2.1 -1.5');$('lens').setAttribute('rotation','0 0 0')}showEntity('lensLabel',false);buildFeatureIsland();showEntity('featureIsland',featureOpen);$('featureIsland').setAttribute('position',compact?'0 .35 .8':'3.5 .7 -1.1');$('featureIsland').setAttribute('scale',compact?'.55 .55 .55':'1 1 1');if($('cafeModel'))showEntity('cafeModel',false);$('featureWorkspace').setAttribute('position',compact?'0 1.05 .8':'3.5 1.95 -1.1');$('featureWorkspace').setAttribute('scale',compact?'.5 .5 .5':'.75 .75 .75');$('featureWorkspace').setAttribute('rotation','0 0 0');window.globiquest.refreshPlayLayout?.(heroX,compact);window.globiquest.layoutXR?.();window.globiquest.restorePanelPlacements?.()}
function openLens(){window.globiquest.artPlay?.stop();releaseLens();const manager=$('earthRoot')?.components?.['globe-rotation'];if(manager?.moving?.id==='lens')manager.release();for(const id of ['lens','toolControls']){const el=$(id);window.globiquest.resetPanelPlacements?.(id);if(el?.dataset){delete el.dataset.panelManual;delete el.dataset.userPlaced}window.globiquest.objectSizer?.forget?.(el)}for(const key of ['lens','lens-panel'])window.globiquest.objectSizer?.positions?.delete(key);setWorkspace('lens',true);showEntity('lens',true);showEntity('toolControls',true);window.globiquest.layoutXR?.();const magic=window.globiquest.magicLens;if(magic){magic.wasVisible=false;magic.aimAtTarget();magic.requestCapture()}return true}
window.globiquest.openLens=openLens;window.globiquest.setWorkspace=setWorkspace;window.globiquest.refreshWorkspace=applyWorkspace;Object.defineProperty(window.globiquest,'workspace',{get:()=>activeWorkspace});document.querySelectorAll('[data-workspace]').forEach(button=>{button.onclick=()=>button.dataset.workspace==='lens'?openLens():setWorkspace(button.dataset.workspace)});$('dockQuest').onclick=()=>openAdventure();window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(featureOpen)closeAdventure();activeWorkspace='home';applyWorkspace()}});window.addEventListener('resize',applyWorkspace);scene.addEventListener('enter-vr',applyWorkspace);scene.addEventListener('exit-vr',applyWorkspace);renderToolControls();applyWorkspace();
if(typeof MutationObserver!=='undefined'){const observer=new MutationObserver(()=>{if(!featureOpen)applyWorkspace()});[...Object.values(workspaceRoots),'novaCaption'].forEach(id=>{if($(id))observer.observe($(id),{childList:true,subtree:true})})}
